<?php
namespace App\Console\Commands;use App\Models\{Category,Product,Service};use App\Services\ImageOptimizationService;use Illuminate\Console\Command;use Illuminate\Support\Str;use Throwable;class OptimizeExistingImages extends Command{protected $signature='media:optimize-existing {--dry-run}';protected $description='Convert locally stored Prinx catalogue images to optimized WebP files';public function handle(ImageOptimizationService $images):int{$count=0;foreach(Product::withTrashed()->get() as$p){if($p->primary_image&&!Str::startsWith($p->primary_image,['http://','https://','/'])&&!Str::endsWith($p->primary_image,'.webp')){if(!$this->option('dry-run'))try{$p->primary_image=$images->optimizeStored($p->primary_image,'products',$p->name,['description'=>$p->meta_description?:$p->short_description]);$p->saveQuietly();}catch(Throwable $e){$this->warn($e->getMessage());continue;}$count++;}}$this->info("Optimized {$count} images.");return self::SUCCESS;}}
